return {["scripts/items/fish_chiefkabob.lua"]={["Path"]="scripts/items/fish_chiefkabob.lua",["SHA256"]="3bb5fceeec2222f11c63e1f18179a777a5b4943471509ae6ed039f82757c107e",["Text"]="-----------------------------------\n-- ID: 4575\n-- Item: fish_chiefkabob\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Dexterity 1\n-- Vitality 2\n-- Mind -1\n-- defense % 25\n-- defense Cap 95\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 1)\n    effect:addMod(xi.mod.VIT, 2)\n    effect:addMod(xi.mod.MND, -1)\n    effect:addMod(xi.mod.FOOD_DEFP, 25)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 95)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/fish_mithkabob.lua"]={["Path"]="scripts/items/fish_mithkabob.lua",["SHA256"]="f662ca9886e459d1b11bc5019acb9f2f06fc44b02965d122909c6f1952c8e05f",["Text"]="-----------------------------------\n-- ID: 4398\n-- Item: fish_mithkabob\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Dexterity 1\n-- Vitality 2\n-- Mind -1\n-- Defense % 25\n-- Defense Cap 90\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 1)\n    effect:addMod(xi.mod.VIT, 2)\n    effect:addMod(xi.mod.MND, -1)\n    effect:addMod(xi.mod.FOOD_DEFP, 25)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 90)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/fishermans_belt.lua"]={["Path"]="scripts/items/fishermans_belt.lua",["SHA256"]="738769d25bc573139c97f781b300b2a836757ffa2c98f4f19736052206800c93",["Text"]="-----------------------------------\n-- ID: 15452\n-- Item: Fisherman's belt\n-- Enchantment: Fishing image support\n-- Duration: 120Min\n-- Fishing Skill +2\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.FISHING_IMAGERY) then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.FISHING_IMAGERY, { power = 2, duration = 120 * 60, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/fishermans_feast.lua"]={["Path"]="scripts/items/fishermans_feast.lua",["SHA256"]="befe3734f71b9ccbd3c386664ae413001fd8bef3fa899ba6c9ae8739c5c17c19",["Text"]="-----------------------------------\n-- ID: 6381\n-- Item: Fisherman's_Feast\n-- Food Effect: 30Min, All Races\n-----------------------------------\n--  Fishing skill gain rate+5%\n--  https://ffxiclopedia.fandom.com/wiki/Fisherman's_Feast\n--  https://www.bg-wiki.com/ffxi/Fisherman%27s_Feast\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FISHING_SKILL_GAIN, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/flame_blade.lua"]={["Path"]="scripts/items/flame_blade.lua",["SHA256"]="1ef2946a995cfa9f27639c3d8a886cc8ed9839b3e5228d9da5b3cee98a5a8185",["Text"]="-----------------------------------\n-- ID: 16565\n-- Item: Flame Blade\n-- Additional effect: fire damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 5,\n        basePower      = math.randomInt(3, 5),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.FIRE,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/flame_blade_+1.lua"]={["Path"]="scripts/items/flame_blade_+1.lua",["SHA256"]="452ae77da55bde8895d989863676fbc3195e95b7ac26bb460190fc2437f50495",["Text"]="-----------------------------------\n-- ID: 16804\n-- Item: Flame Blade\n-- Additional effect: fire damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 5,\n        basePower      = math.randomInt(3, 5),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.FIRE,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/flame_claymore.lua"]={["Path"]="scripts/items/flame_claymore.lua",["SHA256"]="07db269a85e9843