baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 5,\n        basePower      = math.randomInt(3, 5),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.FIRE,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/flame_sword.lua"]={["Path"]="scripts/items/flame_sword.lua",["SHA256"]="643ba1eddc6cd07fc95455684331956bb9bd34cd7fe70d6810a5bd639c977660",["Text"]="-----------------------------------\n-- ID: 16621\n-- Item: Flame Sword\n-- Additional effect: fire damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 5,\n        basePower      = math.randomInt(3, 5),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.FIRE,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/flarelet.lua"]={["Path"]="scripts/items/flarelet.lua",["SHA256"]="6be4f0e866cf413838dc6f49f4cf01c5c14f0b8ae08525d0b85d77a47f1a2f81",["Text"]="-----------------------------------\n-- ID: 6457\n-- Item: Flarelet\n-- A sparkler firework that shoots a purple stream of sparks into the air.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/flask_of_apple_au_lait.lua"]={["Path"]="scripts/items/flask_of_apple_au_lait.lua",["SHA256"]="441ea8e8b258cdec6cc0869719057411e68018d4d22c363f7b160380afc3fd92",["Text"]="-----------------------------------\n-- ID: 4300\n-- Item: Apple au Lait\n-- Item Effect: Restores 120 HP over 180 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local regenEffect = target:getStatusEffect(xi.effect.REGEN)\n\n    if\n        not regenEffect or\n        regenEffect:getTier() == 0\n    then\n        target:delStatusEffectSilent(xi.effect.REGEN) -- All Regen items overwrite freely, and their effect expires silently if overwritten.\n\n        target:addStatusEffect(xi.effect.REGEN, { power = 2, duration = 180, origin = user, tick = 3 })\n    else\n        action:messageID(target:getID(), xi.msg.basic.ITEM_NO_EFFECT) -- Displays no effect when attempting to overwrite tier 1, 2, 3, 4 or 5 Regen.\n\n        return 0\n    end\nend\n\nreturn itemObject\n"},["scripts/items/flask_of_ayran.lua"]={["Path"]="scripts/items/flask_of_ayran.lua",["SHA256"]="7d6c42129c8d9ae40a6339b3a45d48bc357677c233a4b3aef25a2cdb36d66cc4",["Text"]="-----------------------------------\n-- ID: 5576\n-- Item: Ayran\n-- Item Effect: Restores 120 HP over 180 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local regenEffect = target:getStatusEffect(xi.effect.REGEN)\n\n    if\n        not regenEffect or\n        regenEffect:getTier() == 0\n    then\n        target:delStatusEffectSilent(xi.effect.REGEN) -- All Regen items overwrite freely, and their effect expires silently if overwritten.\n\n        target:addStatusEffect(xi.effect.REGEN, { power = 2, duration = 180, origin = user, tick = 3 })\n    else\n        action:messageID(target:getID(), xi.msg.basic.ITEM_NO_EFFECT) -- Displays no effect when attempting to overwrite tier 1, 2, 3, 4 or 5 Regen.\n\n        return 0\n    end\nend\n\nreturn itemObject\n"},["scripts/items/flask_of_blinding_potion.lua"]={["Path"]="scripts/items/flask_of_blinding_potion.lua",["SHA256"]="1955e9250bfc0561e7477acf411a72808249a2838176aa0459c15721ed8a57de",["Text"]="-----------------------------------\n-- ID: 4163\n-- Item: Blinding Potion\n-- Item Effect: This potion induces blindness.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if not target:hasStatusEffect(xi.effect.BLINDNESS) then\n        target:addStatusEffect(xi.effect.BLINDNESS, { power = 256, duration = 180, origin = user })\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/flask_of_deodorizer.lua"]={["Path"]="scripts/items/flask_of_deodorizer.lua",["SHA256"]="2b171d9b18327b78b2a921ab867fab8e01796d8e51472b6b2ee21ac91cf5c717",["Text"]="-----------------------------------\n-- ID: 4166\n-- Deodorizer\n-- When applied, this powerful deodorant neutralizes even the strongest of odors!!.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if  not target:hasStatusEffect(xi.effect.DEODORIZE) then\n        target:addStatusEffect(xi.effect.DEODORIZE, { power = 1, duration = 600, origin = user, tick = 10 })\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/flask_of_distilled_water.lua"]={["Path"]="scripts/items/flask_of_distilled_water.lua",["SHA256"]="394269055ff9e18230ae1c91ecde1250993e8f5f0d1b2785f46e4528241faff9",["Text"]="-----------------------------------\n-- ID: 4509\n-- Item: Flask of distilled water\n-- Item Effect: While Sha Wujing's Lance +1 is equipped:\n--   5m 1HP/tick Regen effect. Lance does not need to remain equipped after use.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local regenEffect = target:getStatusEffect(xi.effect.REGEN)\n\n    if\n        target:getMod(xi.mod.DRINK_DISTILLED) == 1 and -- TODO: Are there other items that need this? Could probably just check if the spear is equipped...\n        (not regenEffect or regenEffect:getTier() == 0)\n    then\n        target:delStatusEffectSilent(xi.effect.REGEN) -- All Regen items overwrite freely, and their effect expires silently if overwritten.\n\n        target:addStatusEffect(xi.effect.REGEN, { power = 1, duration = 300, origin = user, tick = 3 })\n    else\n        action:messageID(target:getID(), xi.msg.basic.ITEM_NO_EFFECT) -- Displays no effect when Lance is not equipped or attempting to overwrite tier 1, 2, 3, 4 or 5 Regen.\n\n        return 0\n    end\nend\n\nreturn itemObject\n"},["scripts/items/flask_of_dragon_fruit_au_lait.lua"]={["Path"]="scripts/items/flask_of_dragon_fruit_au_lait.lua",["SHA256"]="34a89104e4396656cfa5dbcb47ce42149006ab4dacce3a449ba65ae9a4a1f27e",["Text"]="-----------------------------------\n-- ID: 5933\n-- Item: Flask of Dragon Fruit au Lait\n-- Item Effect: Restores 600 HP over 300 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local regenEffect = target:getStatusEffect(xi.effect.REGEN)\n\n    if\n        not regenEffect or\n        regenEffect:getTier() == 0\n    then\n        target:delStatusEffectSilent(xi.effect.REGEN) -- All Regen items overwrite freely, and their effect expires silently if overwritten.\n\n        target:addStatusEffect(xi.effect.REGEN, { power = 6, duration = 300, origin = user, tick = 3 })\n    else\n        action:messageID(target:getID(), xi.msg.basic.ITEM_NO_EFFECT) -- Displays no effect when attempting to overwrite tier 1, 2, 3, 4 or 5 Regen.\n\n        return 0\n    end\nend\n\nreturn itemObject\n"},["scripts/items/flask_of_echo_drops.lua"]={["Path"]="scripts/items/flask_of_echo_drops.lua",["SHA256"]="60bf4cf3f7ebec00abd600f3a8eb793a6daadaa4169c88ec8fd2f002f087becf",["Text"]="-----------------------------------\n-- ID: 4151\n-- Item: Echo Drops\n-- Item Effect: This potion remedies silence.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    if target:hasStatusEffect(xi.effect.SILENCE) then\n        target:delStatusEffect(xi.effect.SILENCE)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/flask_of_eye_drops.lua"]={["Path"]="scripts/items/flask_of_eye_drops.lua",["SHA256"]="41c0f7c29522b69881a8ff90a3ca1a3f0c494645c28d89cfad3b53f4fb0643f0",["Text"]="-----------------------------------\n-- ID: 4150\n-- Item: Eye Drops\n-- Item Effect: This potion remedies blindness.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    if target:hasStatusEffect(xi.effect.BLINDNESS) then\n        target:delStatusEffect(xi.effect.BLINDNESS)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/flask_of_healing_mist.lua"]={["Path"]="scripts/items/flask_of_healing_mist.lua",["SHA256"]="0999a2ce151474f2ea6efd8eea16323bdc15b8d58b339382a6ef2548edc295c2",["Text"]="-----------------------------------\n-- ID: 5832\n-- Item: flask_of_healing_mist\n-- Item Effect: Restores 600 HP to Party members within 10'\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:forMembersInRange(10, function(member)\n        member:messageBasic(xi.msg.basic.RECOVERS_HP, 0, member:addHP(600 * xi.settings.main.ITEM_POWER))\n    end)\nend\n\nreturn itemObject\n"},["scripts/items/flask_of_healing_powder.lua"]={["Path"]="scripts/items/flask_of_healing_powder.lua",["SHA256"]="5f0b223bf48728575aa4c39b6d8a11c7838fb3fc42b45ac1ec73d48e4fc0ad43",["Text"]="-----------------------------------\n-- ID: 5322\n-- Item: flask_of_healing_powder\n-- Item Effect: Restores 25% of Maximum HP to Party members within 10'\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:forMembersInRange(10, function(member)\n        member:messageBasic(xi.msg.basic.RECOVERS_HP, 0, member:addHP((member:getMaxHP() / 100) * 25))\n    end)\nend\n\nreturn itemObject\n"},["scripts/items/flask_of_holy_water.lua"]={["Path"]="scripts/items/flask_of_holy_water.lua",["SHA256"]="2243a8d1175546479236fc4c69cf767271c946d11c45a6b98d010b0374968bb3",["Text"]="-----------------------------------\n-- ID: 4154\n-- Item: Flask of Holy Water\n-- Item Effect: Removes curse\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local curse = target:getStatusEffect(xi.effect.CURSE_I)\n    local curse2 = target:getStatusEffect(xi.effect.CURSE_II)\n    local bane = target:getStatusEffect(xi.effect.BANE)\n    local power = 33 + target:getMod(xi.mod.ENHANCES_HOLYWATER)\n\n    if\n        target:hasStatusEffect(xi.effect.DOOM) and\n        power > math.randomInt(1, 100)\n    then\n        target:delStatusEffect(xi.effect.DOOM)\n        target:messageBasic(xi.msg.basic.NARROWLY_ESCAPE)\n    elseif curse ~= nil and curse2 ~= nil and bane ~= nil then\n        target:delStatusEffect(xi.effect.CURSE_I)\n        target:delStatusEffect(xi.effect.CURSE_II)\n        target:delStatusEffect(xi.effect.BANE)\n    elseif curse ~= nil and bane ~= nil then\n        target:delStatusEffect(xi.effect.CURSE_I)\n        target:delStatusEffect(xi.effect.BANE)\n    elseif curse2 ~= nil and bane ~= nil then\n        target:delStatusEffect(xi.effect.CURSE_II)\n        target:delStatusEffect(xi.effect.BANE)\n    elseif curse ~= nil then\n        target:delStatusEffect(xi.effect.CURSE_I)\n    elseif curse2 ~= nil then\n        target:delStatusEffect(xi.effect.CURSE_II)\n    elseif bane ~= nil then\n        target:delStatusEffect(xi.effect.BANE)\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/flask_of_mana_mist.lua"]={["Path"]="scripts/items/flask_of_mana_mist.lua",["SHA256"]="70124bf173c75e118982a18e775025a962f8f2eb8e245ccc7dd27d2f17b765fc",["Text"]="-----------------------------------\n-- ID: 5833\n-- Item: flask_of_mana_mist\n-- Item Effect: Restores 300 MP to Party members within 10'\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:forMembersInRange(10, function(member)\n        member:messageBasic(xi.msg.basic.RECOVERS_MP, 0, member:addMP(300 * xi.settings.main.ITEM_POWER))\n    end)\nend\n\nreturn itemObject\n"},["scripts/items/flask_of_muting_potion.lua"]={["Path"]="scripts/items/flask_of_muting_potion.lua",["SHA256"]="67b52868dfed307c70f7c3f20051a622abeef116e94e5166711a53d12a3c82ca",["Text"]="-----------------------------------\n-- ID: ???\n-- Item: ???\n-- Item Effect: ???\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nreturn itemObject\n"},["scripts/items/flask_of_orange_au_lait.lua"]={["Path"]="scripts/items/flask_of_orange_au_lait.lua",["SHA256"]="9919eadcaadbd7b5eaeb2df94ec03935f8717cfca753fd81ee58667a22f075c3",["Text"]="-----------------------------------\n-- ID: 4299\n-- Item: Orange au Lait\n-- Item Effect: Restores 100 HP over 300 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local regenEffect = target:getStatusEffect(xi.effect.REGEN)\n\n    if\n        not regenEffect or\n        regenEffect:getTier() == 0\n    then\n        target:delStatusEffectSilent(xi.effect.REGEN) -- All Regen items overwrite freely, and their effect expires silently if overwritten.\n\n        target:addStatusEffect(xi.effect.REGEN, { power = 1, duration = 300, origin = user, tick = 3 })\n    else\n        action:messageID(target:getID(), xi.msg.basic.ITEM_NO_EFFECT) -- Displays no effect when attempting to overwrite tier 1, 2, 3, 4 or 5 Regen.\n\n        return 0\n    end\nend\n\nreturn itemObject\n"},["scripts/items/flask_of_pamama_au_lait.lua"]={["Path"]="scripts/items/flask_of_pamama_au_lait.lua",["SHA256"]="ba35e9415d9369d768cc9ca3dc2c021bdc7dc5c9ccc3eb9730c031eedc27df44",["Text"]="-----------------------------------\n-- ID: 4302\n-- Item: Pamama au Lait\n-- Item Effect: Restores 400 HP over 600 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local regenEffect = target:getStatusEffect(xi.effect.REGEN)\n\n    if\n        not regenEffect or\n        regenEffect:getTier() == 0\n    then\n        target:delStatusEffectSilent(xi.effect.REGEN) -- All Regen items overwrite freely, and their effect expires silently if overwritten.\n\n        target:addStatusEffect(xi.effect.REGEN, { power = 2, duration = 600, origin = user, tick = 3 })\n    else\n        action:messageID(target:getID(), xi.msg.basic.ITEM_NO_EFFECT) -- Displays no effect when attempting to overwrite tier 1, 2, 3, 4 or 5 Regen.\n\n        return 0\n    end\nend\n\nreturn itemObject\n"},["scripts/items/flask_of_panacea.lua"]={["Path"]="scripts/items/flask_of_panacea.lua",["SHA256"]="271eb18d0abdfbcada5a7585a44de375d083341512a0203e63ae40bd6f6b67f7",["Text"]="-----------------------------------\n-- ID: 4163\n-- Item: Panacea\n-- Item Effect: Removes any number of status effects\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:delStatusEffect(xi.effect.ADDLE)\n    target:delStatusEffect(xi.effect.BIND)\n    target:delStatusEffect(xi.effect.SLOW)\n    target:delStatusEffect(xi.effect.WEIGHT)\n\n    target:delStatusEffect(xi.effect.BURN)\n    target:delStatusEffect(xi.effect.FROST)\n    target:delStatusEffect(xi.effect.CHOKE)\n    target:delStatusEffect(xi.effect.RASP)\n    target:delStatusEffect(xi.effect.SHOCK)\n    target:delStatusEffect(xi.effect.DROWN)\n\n    target:delStatusEffect(xi.effect.DIA)\n    target:delStatusEffect(xi.effect.BIO)\n\n    target:delStatusEffect(xi.effect.MAX_HP_DOWN)\n    target:delStatusEffect(xi.effect.MAX_MP_DOWN)\n    target:delStatusEffect(xi.effect.STR_DOWN)\n    target:delStatusEffect(xi.effect.DEX_DOWN)\n    target:delStatusEffect(xi.effect.VIT_DOWN)\n    target:delStatusEffect(xi.effect.AGI_DOWN)\n    target:delStatusEffect(xi.effect.INT_DOWN)\n    target:delStatusEffect(xi.effect.MND_DOWN)\n    target:delStatusEffect(xi.effect.CHR_DOWN)\n\n    target:delStatusEffect(xi.effect.ATTACK_DOWN)\n    target:delStatusEffect(xi.effect.EVASION_DOWN)\n    target:delStatusEffect(xi.effect.DEFENSE_DOWN)\n    target:delStatusEffect(xi.effect.MAGIC_DEF_DOWN)\n    target:delStatusEffect(xi.effect.MAGIC_ACC_DOWN)\n    target:delStatusEffect(xi.effect.MAGIC_ATK_DOWN)\n    target:delStatusEffect(xi.effect.INHIBIT_TP)\nend\n\nreturn itemObject\n"},["scripts/items/flask_of_paralyze_potion.lua"]={["Path"]="scripts/items/flask_of_paralyze_potion.lua",["SHA256"]="f5fa4b893daf62538c12d1344a9057c44e3f97fb6853d0b446a70f04d34f4e3d",["Text"]="-----------------------------------\n-- ID: 4159\n-- Item: Paralyze Potion\n-- Item Effect: This potion induces paralyze.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if not target:hasStatusEffect(xi.effect.PARALYSIS) then\n        target:addStatusEffect(xi.effect.PARALYSIS, { power = 100, duration = 180, origin = user })\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/flask_of_pear_au_lait.lua"]={["Path"]="scripts/items/flask_of_pear_au_lait.lua",["SHA256"]="1fc3f4eff320d543d3a34c98618ca4f9240b02af508ebe907ca90e15dc639411",["Text"]="-----------------------------------\n-- ID: 4301\n-- Item: Pear au Lait\n-- Item Effect: Restores 300 HP over 300 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local regenEffect = target:getStatusEffect(xi.effect.REGEN)\n\n    if\n        not regenEffect or\n        regenEffect:getTier() == 0\n    then\n        target:delStatusEffectSilent(xi.effect.REGEN) -- All Regen items overwrite freely, and their effect expires silently if overwritten.\n\n        target:addStatusEffect(xi.effect.REGEN, { power = 3, duration = 300, origin = user, tick = 3 })\n    else\n        action:messageID(target:getID(), xi.msg.basic.ITEM_NO_EFFECT) -- Displays no effect when attempting to overwrite tier 1, 2, 3, 4 or 5 Regen.\n\n        return 0\n    end\nend\n\nreturn itemObject\n"},["scripts/items/flask_of_persikos_au_lait.lua"]={["Path"]="scripts/items/flask_of_persikos_au_lait.lua",["SHA256"]="f0173923a8d5f24fca2b4c040a9fdd6488b9fff7f7c1350ae9eff5f45b9b2312",["Text"]="-----------------------------------\n-- ID: 4301\n-- Item: Persikos au Lait\n-- Item Effect: Restores 800 HP over 600 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local regenEffect = target:getStatusEffect(xi.effect.REGEN)\n\n    if\n        not regenEffect or\n        regenEffect:getTier() == 0\n    then\n        target:delStatusEffectSilent(xi.effect.REGEN) -- All Regen items overwrite freely, and their effect expires silently if overwritten.\n\n        target:addStatusEffect(xi.effect.REGEN, { power = 4, duration = 600, origin = user, tick = 3 })\n    else\n        action:messageID(target:getID(), xi.msg.basic.ITEM_NO_EFFECT) -- Displays no effect when attempting to overwrite tier 1, 2, 3, 4 or 5 Regen.\n\n        return 0\n    end\nend\n\nreturn itemObject\n"},["scripts/items/flask_of_petrify_potion.lua"]={["Path"]="scripts/items/flask_of_petrify_potion.lua",["SHA256"]="e5d4ca3a1f98f94839477129da78a0e68a37742c1c46c7dcc7398d56329569d1",["Text"]="-----------------------------------\n-- ID: 4160\n-- Item: Petrify Potion\n-- Item Effect: This potion induces petrify.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if not target:hasStatusEffect(xi.effect.PETRIFICATION) then\n        target:addStatusEffect(xi.effect.PETRIFICATION, { power = 1, duration = 180, origin = user, tick = 3 })\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/flask_of_poison_potion.lua"]={["Path"]="scripts/items/flask_of_poison_potion.lua",["SHA256"]="0a3b6cb2c936ba6d531af1074b2483afafdeaa07508efd64edfaa0904d999e7e",["Text"]="-----------------------------------\n-- ID: 4157\n-- Item: Poison Potion\n-- Item Effect: Poison 1HP / Removes 60 HP over 180 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if not target:hasStatusEffect(xi.effect.POISON) then\n        target:addStatusEffect(xi.effect.POISON, { power = 1, duration = 180, origin = user, tick = 3 })\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/flask_of_primeval_brew.lua"]={["Path"]="scripts/items/flask_of_primeval_brew.lua",["SHA256"]="23b6324827ac668e988e5df929cc495ef5e5bb5eae41b81d7bb84f83ca8e1168",["Text"]="-----------------------------------\n-- ID: 5853\n-- Item: Flask of Primeval Brew\n-- Status Effect: 3 minutes, All Races\n-----------------------------------\n-- HP +9000\n-- MP +9000\n-- Strength +900\n-- Dexterity +900\n-- Vitality +900\n-- Agility +900\n-- Intelligence +900\n-- Mind +900\n-- Charisma +900\n-- Attack +9000\n-- Defense +9000\n-- Accuracy +1000\n-- Evasion +1000\n-- Magic Attack Bonus +900\n-- Regen +300\n-- Refresh +300\n-- Regain +50\n-- Ranged Accuracy +1000\n-- Ranged Attack +9000\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.TRANSCENDENCY) then\n        return 523\n    else\n        return 0\n    end\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TRANSCENDENCY, { power = 1, duration = 180, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/flask_of_silencing_potion.lua"]={["Path"]="scripts/items/flask_of_silencing_potion.lua",["SHA256"]="7b344711a6a35798b5c8e73254a3516cc6b7c8cc351e411845fe6f411c96347b",["Text"]="-----------------------------------\n-- ID: 4162\n-- Item: Silencing Potion\n-- Item Effect: This potion induces silence.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if not target:hasStatusEffect(xi.effect.SILENCE) then\n        target:addStatusEffect(xi.effect.SILENCE, { power = 1, duration = 180, origin = user, tick = 3 })\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/flask_of_sleeping_potion.lua"]={["Path"]="scripts/items/flask_of_sleeping_potion.lua",["SHA256"]="7c86bcde214c117708a34bca6d6e703d6a746407e3e28f4d69c14c86bdcfc132",["Text"]="-----------------------------------\n-- ID: 4161\n-- Item: Sleeping Potion\n-- Item Effect: This potion induces sleep.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.SLEEP_I, { power = 1, duration = 30, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/flask_of_strange_milk.lua"]={["Path"]="scripts/items/flask_of_strange_milk.lua",["SHA256"]="169de906d461a9488d2d86ebeee64a3896f337c5eb515acd305c03a5d1b47516",["Text"]="-----------------------------------\n-- ID: 5437\n-- Item: Flask of Strange Milk\n-- Item Effect: Restores 500 HP over 300 seconds.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local regenEffect = target:getStatusEffect(xi.effect.REGEN)\n\n    if\n        not regenEffect or\n        regenEffect:getTier() == 0\n    then\n        target:delStatusEffectSilent(xi.effect.REGEN) -- All Regen items overwrite freely, and their effect expires silently if overwritten.\n\n        target:addStatusEffect(xi.effect.REGEN, { power = 5, duration = 300, origin = user, tick = 3 })\n    else\n        action:messageID(target:getID(), xi.msg.basic.ITEM_NO_EFFECT) -- Displays no effect when attempting to overwrite tier 1, 2, 3, 4 or 5 Regen.\n\n        return 0\n    end\nend\n\nreturn itemObject\n"},["scripts/items/flask_of_venom_potion.lua"]={["Path"]="scripts/items/flask_of_venom_potion.lua",["SHA256"]="1ec0427a88ff6e9e1d76a8aa40442a95f3d580be4a5e2e0b04d082b8e0f1b406",["Text"]="-----------------------------------\n-- ID: 4158\n-- Item: Venom Potion\n-- Item Effect: Removes 300 HP over 180 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if not target:hasStatusEffect(xi.effect.POISON) then\n        target:addStatusEffect(xi.effect.POISON, { power = 5, duration = 180, origin = user, tick = 3 })\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/flask_of_walahra_water.lua"]={["Path"]="scripts/items/flask_of_walahra_water.lua",["SHA256"]="27d9a0f9ac8e9dff258644eb4dcd0bf34f383a89162ae359b1e941980c74b4fc",["Text"]="-----------------------------------\n-- ID: 5354\n-- Item: Flask of Walahra Water\n-- Item Effect: Restores 5% of maximum HP and MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, player, item, action)\n    local hp = math.floor(target:getMaxHP() * 0.05)\n    local mp = math.floor(target:getMaxMP() * 0.05)\n\n    target:addHP(hp)\n    target:addMP(mp)\n    action:messageID(target:getID(), xi.msg.basic.RECOVERS_HP_AND_MP)\n\n    return hp\nend\n\nreturn itemObject\n"},["scripts/items/flexible_pole.lua"]={["Path"]="scripts/items/flexible_pole.lua",["SHA256"]="9660b631b55437cdcc1b2be0c8a37fe00a2bb809a362c8be2a48e3fc57bc04b0",["Text"]="-----------------------------------\n-- ID: 18586\n-- Item: flexible_pole\n-- Item Effect: Attack +3\n-- Duration: 30 Minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.FLEXIBLE_POLE) ~= nil then\n        target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.FLEXIBLE_POLE)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.FLEXIBLE_POLE) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 1800, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.FLEXIBLE_POLE })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.ATT, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/fomalhaut.lua"]={["Path"]="scripts/items/fomalhaut.lua",["SHA256"]="4de74e3bee41db22c5e272ba2372ca6a8ceba9c927f7d80f37d636cb375baeea",["Text"]="-----------------------------------\n-- ID: 22143\n-- Item: Fomalhaut\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getFreeSlotsCount() == 0 then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.CHRONO_BULLET, 99 } }) -- Chrono Bullet x99\nend\n\nreturn itemObject\n"},["scripts/items/forest_carp.lua"]={["Path"]="scripts/items/forest_carp.lua",["SHA256"]="e32d6048f9ee8678066a4a8ba6899875959d2161221d1f4dd3228918e03bd6d6",["Text"]="-----------------------------------\n-- ID: 4289\n-- Item: forest_carp\n-- Food Effect: 30Min, Mithra only\n-----------------------------------\n-- Dexterity 2\n-- Mind -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/forsetis_axe.lua"]={["Path"]="scripts/items/forsetis_axe.lua",["SHA256"]="b341c42332041ee2c50e2b4de8eb045e706993ab670187cae53460393c36a6ad",["Text"]="-----------------------------------\n-- ID: 16726\n-- Item: Forseti's Axe\n-- Additional effect: Wind damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local chance = 3 -- TODO: check scaling on non-windssday\n    local power  = 4 + utils.clamp(dStat * 35 / 54, 0, 35)\n\n    if VanadielDayOfTheWeek() == xi.day.FIRESDAY then\n        chance = xi.additionalEffect.linearProcRate(dStat, 140, 15, 50) -- Numbers are smoothed out a bit. Scale from 15% at dINT 0 to 50% at +140 DINT\n    end\n\n    local pTable =\n    {\n        chance         = chance,\n        basePower      = math.randomInt(power, power + 3),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.WIND,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/four-leaf_mandragora_bud.lua"]={["Path"]="scripts/items/four-leaf_mandragora_bud.lua",["SHA256"]="c577c5922478dd9811215ef6d4efa1e43f1ed7291123096eeb872dfbbab9a75f",["Text"]="-----------------------------------\n-- ID: 4369\n-- Item: four-leaf_mandragora_bud\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Agility 3\n-- Vitality -5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 3)\n    effect:addMod(xi.mod.VIT, -5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/fourth_staff.lua"]={["Path"]="scripts/items/fourth_staff.lua",["SHA256"]="b1caa5675ebbaef01d227b8aaefcdebdaf58419b8470513a7b611b453f11d49b",["Text"]="-----------------------------------\n-- ID: 18613\n-- Fourth Staff\n-- Enchantment: \"Retrace\" (Bastok Markets[S])\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.BASTOK_MARKETS_S, duration = 3, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/fractus_cell.lua"]={["Path"]="scripts/items/fractus_cell.lua",["SHA256"]="bf9dc2df0b5013c941c9d3db7775eb076e00ab2ee62257ced53338b0aa61d310",["Text"]="-----------------------------------\n-- Fractus Cell\n-- 5377\n-- Removes DEX Down effect\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.salvage.onCellItemCheck(target, xi.effect.DEBILITATION, 0x002)\nend\n\nitemObject.onItemUse = function(target)\n    return xi.salvage.onCellItemUse(target, xi.effect.DEBILITATION, 0x002, 12)\nend\n\nreturn itemObject\n"},["scripts/items/fried_popoto.lua"]={["Path"]="scripts/items/fried_popoto.lua",["SHA256"]="b9a26a252d7a9cfd6f6fd02402093eb26a1faa4cbd5f839140fda9f2be6cdb26",["Text"]="-----------------------------------\n-- ID: 6272\n-- Item: fried_popoto\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- HP +30\n-- VIT +2\n-- Fire resistance +20\n-- DEF +20% (cap 145)\n-- Subtle Blow +8\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 30)\n    effect:addMod(xi.mod.VIT, 2)\n    effect:addMod(xi.mod.FIRE_MEVA, 20)\n    effect:addMod(xi.mod.FOOD_DEFP, 20)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 145)\n    effect:addMod(xi.mod.SUBTLE_BLOW, 8)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/fried_popoto_+1.lua"]={["Path"]="scripts/items/fried_popoto_+1.lua",["SHA256"]="8733f21a236ddffc0f1dd2f1c07b71c5a6750e9f683b9fa625b2a3eec4bf1763",["Text"]="-----------------------------------\n-- ID: 6273\n-- Item: fried_popoto_+1\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- HP +35\n-- VIT +3\n-- Fire resistance +21\n-- DEF +21% (cap 150)\n-- Subtle Blow +9\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 35)\n    effect:addMod(xi.mod.VIT, 3)\n    effect:addMod(xi.mod.FIRE_MEVA, 21)\n    effect:addMod(xi.mod.FOOD_DEFP, 21)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 150)\n    effect:addMod(xi.mod.SUBTLE_BLOW, 9)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/frost_turnip.lua"]={["Path"]="scripts/items/frost_turnip.lua",["SHA256"]="c861580b8db0f07a90eb183eee47d3462443893d4d38c627836bc410163f01fa",["Text"]="-----------------------------------\n-- ID: 4382\n-- Item: frost_turnip\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility 2\n-- Vitality -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 2)\n    effect:addMod(xi.mod.VIT, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/frostreaper.lua"]={["Path"]="scripts/items/frostreaper.lua",["SHA256"]="7f156939f9c2dcba20b440b3beb5aaed78c16fc82ae80097b3c15fa7e725eedb",["Text"]="-----------------------------------\n-- ID: 16784\n-- Item: Frostreaper\n-- Additional effect: ice damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = 4 + utils.clamp(dStat * 8 / 54, 0, 8), -- linear interpolation\n        basePower      = math.randomInt(9, 12),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.ICE,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/fruit_parfait.lua"]={["Path"]="scripts/items/fruit_parfait.lua",["SHA256"]="7aa7539c0976ba4b44d69c0916a5bb536ec3f934d1590b3c5d62c002bfdee835",["Text"]="-----------------------------------\n-- ID: 6063\n-- Item: fruit_parfait\n-- Food Effect: 180 Min, All Races\n-----------------------------------\n-- MP+5% (Upper limit 50)\n-- INT+3\n-- MND+2\n-- CHR+1\n-- STR-3\n-- MACC+3\n-- MAB+6\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 5)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 50)\n    effect:addMod(xi.mod.INT, 3)\n    effect:addMod(xi.mod.MND, 2)\n    effect:addMod(xi.mod.CHR, 1)\n    effect:addMod(xi.mod.STR, -3)\n    effect:addMod(xi.mod.MACC, 3)\n    effect:addMod(xi.mod.MATT, 6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/fudgy-wudge.lua"]={["Path"]="scripts/items/fudgy-wudge.lua",["SHA256"]="157b790fdd8fe611e7e7e76b53afba793bab442e31fe5d76396068408b8f4c87",["Text"]="-----------------------------------\n-- ID: 5920\n-- Item: Fudgy-wudge\n-- Food Effect: 3 Min, All Races\n-----------------------------------\n-- Intelligence 1\n-- Base speed 10% or +5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 180, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.INT, 1)\n    effect:addMod(xi.mod.MOVE_SPEED_QUICKENING, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/fulm-long_salmon_sub.lua"]={["Path"]="scripts/items/fulm-long_salmon_sub.lua",["SHA256"]="e8300906c081864a1f94e7b10a171b508137477f773449657ba09d5be42e1b63",["Text"]="-----------------------------------\n-- ID: 4266\n-- Item: fulm-long_salmon_sub\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- DEX +2\n-- VIT +1\n-- AGI +1\n-- INT +2\n-- MND -2\n-- Ranged Accuracy +3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.VIT, 1)\n    effect:addMod(xi.mod.AGI, 1)\n    effect:addMod(xi.mod.INT, 2)\n    effect:addMod(xi.mod.MND, -2)\n    effect:addMod(xi.mod.RACC, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/fuma_shuriken_pouch.lua"]={["Path"]="scripts/items/fuma_shuriken_pouch.lua",["SHA256"]="090aa6e7371ad1308252de72075ba009f4386f6a5de00d3f5cfe994ab66d32a5",["Text"]="-----------------------------------\n-- ID: 6302\n-- Item: Fuma Sh. Pouch\n-- When used, you will obtain one stack of Fuma Shurikens\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.FUMA_SHURIKEN, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/fuscina.lua"]={["Path"]="scripts/items/fuscina.lua",["SHA256"]="ec618a9e4e43bd45255631c696871f2cac3352f1cdd9ff2d886a35364b8fc2c0",["Text"]="-----------------------------------\n-- ID: 18104\n-- Item: Fuscina\n-- Additional effect: lightning damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 5,\n        basePower      = math.randomInt(3, 5),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.THUNDER,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/fusion_bolt_quiver.lua"]={["Path"]="scripts/items/fusion_bolt_quiver.lua",["SHA256"]="c6b28f2b62d5c8a19889f2b571abdcdf2bb450cbd249669417acf81efb3e7a76",["Text"]="-----------------------------------\n-- ID: 5821\n-- Fusion Bolt Quiver\n-- When used, you will obtain one stack of Fusion Bolts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.FUSION_BOLT, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/galette_des_rois.lua"]={["Path"]="scripts/items/galette_des_rois.lua",["SHA256"]="d1e363253b592c605c58115bd1dfe972390d95c50d2c90988aebbea983cf0a96",["Text"]="-----------------------------------\n-- ID: 5875\n-- Item: Galette Des Rois\n-- Food Effect: 180 Min, All Races\n-----------------------------------\n-- HP +8\n-- MP +3% (cap13)\n-- Intelligence +2\n-- Random Jewel\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if target:hasStatusEffect(xi.effect.FOOD) then\n        result = xi.msg.basic.IS_FULL\n    end\n\n    if target:getFreeSlotsCount() == 0 then\n        result = xi.msg.basic.ITEM_NO_USE_INVENTORY\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\n    local rand = math.randomInt(784, 815)\n    npcUtil.giveItem(target, { { rand, 1 } })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 8)\n    effect:addMod(xi.mod.FOOD_MPP, 3)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 13)\n    effect:addMod(xi.mod.INT, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/galkan_sausage.lua"]={["Path"]="scripts/items/galkan_sausage.lua",["SHA256"]="6e2f61567d0c5b9e933ea7dac71e49857e67d12b73ebd73195f1b219dff4fca3",["Text"]="-----------------------------------\n-- ID: 4395\n-- Item: galkan_sausage\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Multi-Race Effects\n-- Galka\n-- Strength 3\n-- Intelligence -1\n-- Attack % 25\n-- Attack Cap 30\n-- Ranged ATT % 25\n-- Ranged ATT Cap 30\n--\n-- Other\n-- Strength 3\n-- Intelligence -4\n-- Attack 9\n-- Ranged ATT  9\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    if target:getRace() ~= xi.race.GALKA then\n        effect:addMod(xi.mod.STR, 3)\n        effect:addMod(xi.mod.INT, -4)\n        effect:addMod(xi.mod.ATT, 9)\n        effect:addMod(xi.mod.RATT, 9)\n    else\n        effect:addMod(xi.mod.STR, 3)\n        effect:addMod(xi.mod.INT, -1)\n        effect:addMod(xi.mod.FOOD_ATTP, 25)\n        effect:addMod(xi.mod.FOOD_ATT_CAP, 30)\n        effect:addMod(xi.mod.FOOD_RATTP, 25)\n        effect:addMod(xi.mod.FOOD_RATT_CAP, 30)\n    end\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/galkan_sausage_+1.lua"]={["Path"]="scripts/items/galkan_sausage_+1.lua",["SHA256"]="a0c919be6f5ed6461bc9b8cce78cf12c3171c9a02e55936dda1cedf6132eacc4",["Text"]="-----------------------------------\n-- ID: 5859\n-- Item: galkan_sausage_+1\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Strength 4\n-- Intelligence -5\n-- Attack 10\n-- Ranged Attack 10\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 4)\n    effect:addMod(xi.mod.INT, -5)\n    effect:addMod(xi.mod.ATT, 10)\n    effect:addMod(xi.mod.RATT, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/galkan_sausage_+2.lua"]={["Path"]="scripts/items/galkan_sausage_+2.lua",["SHA256"]="d824251b18898f959ffe354a4d99cb276da3b5842fab718b46a8afb9a7d33f12",["Text"]="-----------------------------------\n-- ID: 5860\n-- Item: galkan_sausage_+2\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Strength 5\n-- Intelligence -6\n-- Attack 11\n-- Ranged Attack 11\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 5)\n    effect:addMod(xi.mod.INT, -6)\n    effect:addMod(xi.mod.ATT, 11)\n    effect:addMod(xi.mod.RATT, 11)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/galkan_sausage_+3.lua"]={["Path"]="scripts/items/galkan_sausage_+3.lua",["SHA256"]="88ea72993043c2dfe50c6310e7792e9cd9cbde7db65b1c5afee01858ca15a2df",["Text"]="-----------------------------------\n-- ID: 5861\n-- Item: galkan_sausage_+3\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Strength 6\n-- Intelligence -7\n-- Attack 12\n-- Ranged Attack 12\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 6)\n    effect:addMod(xi.mod.INT, -7)\n    effect:addMod(xi.mod.ATT, 12)\n    effect:addMod(xi.mod.RATT, 12)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/galkan_sausage_-1.lua"]={["Path"]="scripts/items/galkan_sausage_-1.lua",["SHA256"]="0541ab5c3c2a07526478cdeca10419d0c42daba3053b56ffdaafa1e8cb2e5b5e",["Text"]="-----------------------------------\n-- ID: 5862\n-- Item: galkan_sausage_-1\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Strength -3\n-- Dexterity -3\n-- Vitality -3\n-- Agility -3\n-- Mind -3\n-- Intelligence -3\n-- Charisma -3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, -3)\n    effect:addMod(xi.mod.DEX, -3)\n    effect:addMod(xi.mod.VIT, -3)\n    effect:addMod(xi.mod.AGI, -3)\n    effect:addMod(xi.mod.MND, -3)\n    effect:addMod(xi.mod.INT, -3)\n    effect:addMod(xi.mod.CHR, -3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/gamushara_earring.lua"]={["Path"]="scripts/items/gamushara_earring.lua",["SHA256"]="bfc28ab7174f6a838f2b06965039a75045a22ff1be3e31f3cc362676d039852e",["Text"]="-----------------------------------\n-- ID: 14788\n-- Item: Gamushara Earring\n-- Item Effect: Attack +22\n-- Duration: 3 Minutes\n-- https://wiki.ffo.jp/html/10068.html\n-- TODO: Capture Icon\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.GAMUSHARA_EARRING) then\n        local effect = target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.GAMUSHARA_EARRING)\n        if effect then\n            effect:resetStartTime()\n        else\n            target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.GAMUSHARA_EARRING })\n        end\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.ATT, 22)\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.GAMUSHARA_EARRING)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/gandiva.lua"]={["Path"]="scripts/items/gandiva.lua",["SHA256"]="7d34e629c8d5633aa5eaadafd384d8fc0af048344595191af036f23fac9d31c2",["Text"]="-----------------------------------\n-- ID: 19468\n-- Item: Gandiva\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getFreeSlotsCount() == 0 then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.ARTEMIS_ARROW, 99 } }) -- Artemis' Arrow x99\nend\n\nreturn itemObject\n"},["scripts/items/gargouille_quiver.lua"]={["Path"]="scripts/items/gargouille_quiver.lua",["SHA256"]="7c2935530bb6ab86487984bdfb8ff8d400092450c3ebaaa5efb8e7fc703dffdb",["Text"]="-----------------------------------\n-- ID: 5912\n-- Gargouille Quiver\n-- When used, you will obtain one stack of Gargouille Arrow\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.GARGOUILLE_ARROW, 99 } })\nend\n\nreturn itemObject\n"}};
